/*-----------------------------------------------------------
 * Debug / trace
 *----------------------------------------------------------*/
#define configUSE_TRACE_FACILITY                 1   /* vTaskList(), uxTaskGetSystemState() */
#define configUSE_STATS_FORMATTING_FUNCTIONS     1

/* Run-time stats (vTaskGetRunTimeStats(), "Run Time" column in the IDE's
 * FreeRTOS Task List view). Counter = DWT cycle counter, runs at the CPU
 * clock (72 MHz) -> 32-bit value wraps every ~60 s, so the percentages are
 * only valid for measurements shorter than that. */
#define configGENERATE_RUN_TIME_STATS            1
#define portCONFIGURE_TIMER_FOR_RUN_TIME_STATS() configureTimerForRunTimeStats()
#define portGET_RUN_TIME_COUNTER_VALUE()         getRunTimeCounterValue()

/*-----------------------------------------------------------
 * Kernel objects
 *----------------------------------------------------------*/
#define configUSE_TASK_NOTIFICATIONS             1
#define configUSE_MUTEXES                        1
