//#define configTIMER_TASK_STACK_DEPTH             ( configMINIMAL_STACK_SIZE * 2 )
//#define configTIMER_QUEUE_LENGTH                 10

/*-----------------------------------------------------------
 * Cortex-M interrupt priorities
 *
 * STM32F7 implements 4 priority bits -> 0 (highest) .. 15 (lowest).
 * Any ISR that calls a ...FromISR() API MUST have a NVIC priority
 * numerically >= configLIBRARY_MAX_SYSCALL_INTERRUPT_PRIORITY (5..15).
 * Set it in CubeMX: System Core > NVIC.
 *----------------------------------------------------------*/
#ifdef __NVIC_PRIO_BITS
    #define configPRIO_BITS                      __NVIC_PRIO_BITS
#else
    #define configPRIO_BITS                      4
#endif

#define configLIBRARY_LOWEST_INTERRUPT_PRIORITY       15
#define configLIBRARY_MAX_SYSCALL_INTERRUPT_PRIORITY  5

#define configKERNEL_INTERRUPT_PRIORITY \
    ( configLIBRARY_LOWEST_INTERRUPT_PRIORITY << ( 8 - configPRIO_BITS ) )
#define configMAX_SYSCALL_INTERRUPT_PRIORITY \
    ( configLIBRARY_MAX_SYSCALL_INTERRUPT_PRIORITY << ( 8 - configPRIO_BITS ) )

/*-----------------------------------------------------------
 * Assert: stops the CPU and prints file/line on the UART
 *----------------------------------------------------------*/
#define configASSERT( x )    if( ( x ) == 0 ) { vAssertCalled( __FILE__, __LINE__ ); }

/*-----------------------------------------------------------
 * Optional API functions (1 = include)
 *----------------------------------------------------------*/
//#define INCLUDE_xTimerPendFunctionCall           1
#define INCLUDE_eTaskGetState                    1
#define INCLUDE_uxTaskGetStackHighWaterMark      1
#define INCLUDE_uxTaskPriorityGet                1
#define INCLUDE_vTaskDelay                       1
#define INCLUDE_vTaskDelete                      1
#define INCLUDE_vTaskPrioritySet                 1
#define INCLUDE_vTaskSuspend                     1
#define INCLUDE_xSemaphoreGetMutexHolder         1
#define INCLUDE_xTaskAbortDelay                  1
#define INCLUDE_xTaskDelayUntil                  1
#define INCLUDE_xTaskGetCurrentTaskHandle        1
#define INCLUDE_xTaskGetHandle                   1
#define INCLUDE_xTaskGetIdleTaskHandle           1
#define INCLUDE_xTaskGetSchedulerState           1
#define INCLUDE_xTaskResumeFromISR               1

/*-----------------------------------------------------------
 * Map the FreeRTOS port handlers onto the CMSIS vector names used by
 * startup_stm32f756zgtx.s.  This is why CubeMX must NOT generate
 * SVC_Handler / PendSV_Handler / SysTick_Handler in stm32f7xx_it.c
 * (System Core > NVIC > Code generation > "Generate IRQ handler" unchecked)
 * and why the HAL time base uses TIM6 instead of SysTick.
 *----------------------------------------------------------*/
#define vPortSVCHandler      SVC_Handler
#define xPortPendSVHandler   PendSV_Handler
#define xPortSysTickHandler  SysTick_Handler

#endif /* FREERTOS_CONFIG_H */
